object Solution { def fractionToDecimal(numerator: Int, denominator: Int): String = { if (numerator == 0) return "0"; val result = new StringBuilder; var n = numerator.toLong; var d = denominator.toLong; if ((n < 0) != (d < 0)) result.append('-'); n = math.abs(n); d = math.abs(d); result.append(n / d); var remainder = n % d; if (remainder == 0) return result.toString; result.append('.'); val seen = scala.collection.mutable.Map[Long, Int](); while (remainder != 0) { seen.get(remainder) match { case Some(index) => result.insert(index, '('); result.append(')'); remainder = 0; case None => seen(remainder) = result.length; remainder *= 10; result.append(remainder / d); remainder %= d } }; result.toString } }